{"version":3,"file":"main.js","sources":["pages/doctor/schedule/main.vue","../../../../../../../HBuilderX/plugins/uniapp-cli-vite/uniPage:/cGFnZXMvZG9jdG9yL3NjaGVkdWxlL21haW4udnVl"],"sourcesContent":["<template> \r\n  <view class=\"schedule-page\"> \r\n    <!-- 顶部医生信息 --> \r\n    <view class=\"doctor-header\"> \r\n      <view class=\"doctor-info\"> \r\n        <text class=\"doctor-name\">{{ doctorInfo.name || '张医生' }}</text> \r\n        <text class=\"doctor-dept\">{{ doctorInfo.department || '内科' }}</text> \r\n      </view> \r\n      <text class=\"today-date\">{{ todayDate }}</text> \r\n    </view> \r\n\r\n    <!-- 日期选择器 --> \r\n    <view class=\"date-selector\"> \r\n      <scroll-view scroll-x class=\"date-scroll\"> \r\n        <view \r\n          v-for=\"(date, index) in dateList\" \r\n          :key=\"index\" \r\n          class=\"date-item\" \r\n          :class=\"{ active: selectedDateIndex === index }\" \r\n          @click=\"selectDate(index)\" \r\n        > \r\n          <text class=\"date-weekday\">{{ date.weekday }}</text> \r\n          <text class=\"date-day\">{{ date.day }}</text> \r\n          <text class=\"date-month\">{{ date.month }}</text> \r\n        </view> \r\n      </scroll-view> \r\n    </view> \r\n\r\n    <!-- 排班列表 --> \r\n    <view class=\"schedule-container\"> \r\n      <view class=\"section-title\"> \r\n        <text class=\"title-text\">当日出诊排班</text> \r\n      </view> \r\n\r\n      <view v-if=\"scheduleList.length === 0\" class=\"empty-state\"> \r\n        <text class=\"empty-text\">暂无排班信息</text> \r\n      </view> \r\n\r\n      <view v-else class=\"schedule-list\"> \r\n        <view \r\n          v-for=\"(item, index) in scheduleList\" \r\n          :key=\"index\" \r\n          class=\"schedule-item\" \r\n        > \r\n          <view class=\"schedule-header\"> \r\n            <view class=\"time-period\"> \r\n              <text class=\"period-icon\">⏰</text> \r\n              <text class=\"period-text\">{{ item.timePeriod }}</text> \r\n            </view> \r\n            <view class=\"status-tag\" :class=\"getStatusClass(item)\"> \r\n              {{ getStatusText(item) }} \r\n            </view> \r\n          </view> \r\n\r\n          <view class=\"schedule-info\"> \r\n            <view class=\"info-item\"> \r\n              <text class=\"info-label\">诊室号：</text> \r\n              <text class=\"info-value\">{{ item.roomNumber }}</text> \r\n            </view> \r\n            <view class=\"info-item\"> \r\n              <text class=\"info-label\">可预约：</text> \r\n              <text class=\"info-value\">{{ item.totalSlots }}人</text> \r\n            </view> \r\n            <view class=\"info-item\"> \r\n              <text class=\"info-label\">已挂号：</text> \r\n              <text class=\"info-value appointment-count\">{{ item.bookedSlots }}人</text> \r\n            </view> \r\n            <view class=\"info-item\"> \r\n              <text class=\"info-label\">剩余号源：</text> \r\n              <text class=\"info-value remaining\" :class=\"{ 'low-remaining': item.remainingSlots < 3 }\"> \r\n                {{ item.remainingSlots }}人 \r\n              </text> \r\n            </view> \r\n          </view> \r\n        </view> \r\n      </view> \r\n    </view> \r\n\r\n    <!-- 操作按钮 --> \r\n    <view class=\"action-section\"> \r\n      <button class=\"action-btn refresh-btn\" @click=\"handleRefresh\"> \r\n        🔄 刷新排班 \r\n      </button>\r\n      <button class=\"action-btn adjust-btn\" @click=\"goToAdjustSchedule\"> \r\n        申请调班 \r\n      </button> \r\n    </view> \r\n\r\n    <!-- 底部导航 --> \r\n    <view class=\"bottom-nav\"> \r\n      <view class=\"nav-item\" @click=\"goToPatients\"> \r\n        <text class=\"nav-icon\">👥</text> \r\n        <text class=\"nav-text\">患者详情</text> \r\n      </view> \r\n      <view class=\"nav-item\" @click=\"goToProfile\"> \r\n        <text class=\"nav-icon\">👤</text> \r\n        <text class=\"nav-text\">个人信息</text> \r\n      </view> \r\n    </view> \r\n  </view> \r\n</template> \r\n\r\n<script setup> \r\nimport { ref, onMounted, computed } from 'vue' \r\nimport { uniNavigateTo, uniShowToast } from '../../../utils/uniHelper' \r\nimport { useUserStore } from '../../../store/user.js'\r\nimport { doctorApi } from '../../../api/doctor'\r\n\r\n// 用接口数据填充页头信息与 doctorId\r\nconst userStore = useUserStore()\r\nconst doctorInfo = ref({ \r\n  name: '', \r\n  department: '' \r\n}) \r\n// 修复：去掉 TS 泛型，使用纯 JS\r\nconst doctorIdRef = ref(null)\r\nconst doctorId = computed(() => doctorIdRef.value ?? userStore.userInfo?.doctorId ?? 1)\r\n\r\n// 初始化页头的医生信息\r\nconst initDoctorInfo = async () => {\r\n  try {\r\n    userStore.initFromStorage()\r\n    const userId = userStore.userInfo?.userId\r\n    if (!userId) return\r\n    const profile = await doctorApi.getProfileByUserId(userId)\r\n    doctorInfo.value = {\r\n      name: profile?.doctorName || profile?.realname || '未命名',\r\n      department: profile?.deptName || '—'\r\n    }\r\n    doctorIdRef.value = profile?.doctorId ?? null\r\n  } catch (e) {\r\n    // 保留占位信息即可\r\n  }\r\n}\r\n\r\n// 当前日期\r\nconst todayDate = ref('') \r\n\r\n// 日期列表（未来7天）\r\nconst dateList = ref([]) \r\nconst selectedDateIndex = ref(0) \r\n\r\n// 排班列表\r\nconst scheduleList = ref([]) \r\n\r\nconst fmtDate = (d) => `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`\r\n\r\nconst initDateList = () => { \r\n  const dates = [] \r\n  const weekdays = ['周日', '周一', '周二', '周三', '周四', '周五', '周六'] \r\n  for (let i = 0; i < 7; i++) { \r\n    const date = new Date() \r\n    date.setDate(date.getDate() + i) \r\n    dates.push({ \r\n      weekday: weekdays[date.getDay()], \r\n      day: date.getDate(), \r\n      month: `${date.getMonth() + 1}月`, \r\n      fullDate: date \r\n    }) \r\n  } \r\n  dateList.value = dates \r\n  const today = new Date() \r\n  todayDate.value = `${today.getFullYear()}年${today.getMonth() + 1}月${today.getDate()}日` \r\n} \r\n\r\n// 选择日期\r\nconst selectDate = (index) => { \r\n  selectedDateIndex.value = index \r\n  loadScheduleData() \r\n} \r\n\r\n// 加载后端排班数据\r\nconst labelFromRange = (range) => {\r\n  if (range === '08:00-12:00') return `上午 ${range}`\r\n  if (range === '14:00-17:00') return `下午 ${range}`\r\n  if (range === '18:00-20:00') return `晚上 ${range}`\r\n  return range\r\n}\r\n\r\nconst loadScheduleData = async () => { \r\n  try {\r\n    const sel = dateList.value[selectedDateIndex.value]\r\n    const startDate = fmtDate(sel.fullDate)\r\n    const resp = await doctorApi.getSchedules(doctorId.value, startDate, 1)\r\n    scheduleList.value = (resp || []).map(s => ({\r\n      timePeriod: labelFromRange(s.timeRange),\r\n      roomNumber: s.roomNo || 'A-101',\r\n      totalSlots: s.totalSlots || 0,\r\n      bookedSlots: s.bookedCount || 0,\r\n      remainingSlots: (s.totalSlots || 0) - (s.bookedCount || 0)\r\n    }))\r\n  } catch (e) {\r\n    // 回退到本地模拟\r\n    const mockData = [ \r\n      { timePeriod: '上午 08:00-12:00', roomNumber: '101', totalSlots: 20, bookedSlots: 15, remainingSlots: 5 }, \r\n      { timePeriod: '下午 14:00-17:00', roomNumber: '101', totalSlots: 15, bookedSlots: 13, remainingSlots: 2 }, \r\n      { timePeriod: '晚上 18:00-20:00', roomNumber: '102', totalSlots: 10, bookedSlots: 5, remainingSlots: 5 } \r\n    ] \r\n    scheduleList.value = mockData \r\n  }\r\n} \r\n\r\n// 跳转到申请调班（映射到已存在的页面路径）\r\nconst goToAdjustSchedule = () => { \r\n  uniNavigateTo({ url: '/pages/doctor/schedule/apply' }) \r\n} \r\n\r\n// 跳转到患者列表（映射到已存在的页面路径）\r\nconst goToPatients = () => { \r\n  uniNavigateTo({ url: '/pages/doctor/patients/list' }) \r\n} \r\n\r\n// 跳转到个人信息（映射到已存在的页面路径）\r\nconst goToProfile = () => { \r\n  uniNavigateTo({ url: '/pages/doctor/profile/index' }) \r\n}\r\n\r\n// 刷新排班数据\r\nconst handleRefresh = async () => {\r\n  uniShowToast({ title: '正在刷新...', icon: 'loading' })\r\n  try {\r\n    await loadScheduleData()\r\n    uniShowToast({ title: '刷新成功', icon: 'success' })\r\n  } catch (error) {\r\n    uniShowToast({ title: '刷新失败', icon: 'error' })\r\n  }\r\n} \r\n\r\n// 根据剩余号源与占用比，返回状态的样式类\r\nconst getStatusClass = (item) => {\r\n  const total = item?.totalSlots ?? 0\r\n  const booked = item?.bookedSlots ?? 0\r\n  const remaining = item?.remainingSlots ?? (total - booked)\r\n  if (remaining <= 0) return 'status-full'\r\n  const ratio = total > 0 ? booked / total : 0\r\n  if (remaining < 3 || ratio >= 0.7) return 'status-busy'\r\n  return 'status-available'\r\n}\r\n\r\n// 根据样式类返回显示文案\r\nconst getStatusText = (item) => {\r\n  const cls = getStatusClass(item)\r\n  if (cls === 'status-full') return '已满'\r\n  if (cls === 'status-busy') return '紧张'\r\n  return '可预约'\r\n}\r\n\r\nonMounted(() => { \r\n  userStore.initFromStorage()\r\n  initDateList()\r\n  initDoctorInfo().finally(loadScheduleData)\r\n}) \r\n</script> \r\n\r\n<style scoped> \r\n.schedule-page { \r\n  min-height: 100vh; \r\n  background: #f7faff; \r\n  padding-bottom: 140rpx; \r\n} \r\n\r\n/* 顶部医生信息 */ \r\n.doctor-header { \r\n  background: linear-gradient(90deg, #479fff 0%, #2176ff 100%); \r\n  padding: 24rpx; \r\n  display: flex; \r\n  align-items: center; \r\n  justify-content: space-between; \r\n} \r\n.doctor-info { color: #fff; } \r\n.doctor-name { font-size: 36rpx; font-weight: 700; } \r\n.doctor-dept { font-size: 26rpx; opacity: 0.9; margin-top: 6rpx; display: block; } \r\n.today-date { color: #fff; font-size: 26rpx; } \r\n\r\n/* 日期选择器 */ \r\n.date-selector { margin-top: 12rpx; background: #fff; } \r\n.date-scroll { white-space: nowrap; padding: 12rpx; } \r\n.date-item { \r\n  display: inline-flex; \r\n  flex-direction: column; \r\n  align-items: center; \r\n  justify-content: center; \r\n  width: 120rpx; \r\n  height: 120rpx; \r\n  margin-right: 12rpx; \r\n  background: #f1f5f9; \r\n  border-radius: 16rpx; \r\n  box-shadow: 0 4rpx 12rpx rgba(33,118,255,0.06); \r\n  color: #334155; \r\n} \r\n.date-item.active { \r\n  background: linear-gradient(180deg, #e6f1ff 0%, #ffffff 100%); \r\n  border: 2rpx solid #479fff; \r\n  color: #2176ff; \r\n} \r\n.date-weekday { font-size: 24rpx; } \r\n.date-day { font-size: 36rpx; font-weight: 700; } \r\n.date-month { font-size: 24rpx; } \r\n\r\n/* 排班列表 */ \r\n.schedule-container { padding: 24rpx; } \r\n.section-title .title-text { font-size: 30rpx; color: #1e293b; font-weight: 600; } \r\n.empty-state { \r\n  background: #fff; \r\n  border-radius: 16rpx; \r\n  padding: 32rpx; \r\n  text-align: center; \r\n  color: #64748b; \r\n  margin-top: 16rpx; \r\n} \r\n.schedule-list { margin-top: 16rpx; } \r\n.schedule-item { \r\n  background: #fff; \r\n  border-radius: 16rpx; \r\n  padding: 16rpx; \r\n  margin-bottom: 12rpx; \r\n  box-shadow: 0 6rpx 16rpx rgba(33,118,255,0.08); \r\n} \r\n.schedule-header { display: flex; justify-content: space-between; align-items: center; } \r\n.time-period { display: flex; align-items: center; gap: 8rpx; } \r\n.period-icon { font-size: 26rpx; } \r\n.period-text { font-size: 28rpx; font-weight: 600; color: #0f172a; } \r\n.status-tag { \r\n  padding: 6rpx 12rpx; \r\n  border-radius: 999rpx; \r\n  font-size: 24rpx; \r\n} \r\n.status-available { background: #e0f2fe; color: #0369a1; } \r\n.status-busy { background: #fef3c7; color: #b45309; } \r\n.status-full { background: #fee2e2; color: #b91c1c; } \r\n\r\n.schedule-info { \r\n  display: grid; \r\n  grid-template-columns: 1fr 1fr; \r\n  gap: 8rpx 12rpx; \r\n  margin-top: 12rpx; \r\n} \r\n.info-item { display: flex; align-items: center; } \r\n.info-label { color: #64748b; font-size: 26rpx; } \r\n.info-value { color: #0f172a; font-size: 26rpx; font-weight: 600; } \r\n.appointment-count { color: #0ea5e9; } \r\n.remaining { color: #10b981; } \r\n.low-remaining { color: #ef4444; } \r\n\r\n/* 操作按钮 */ \r\n.action-section { \r\n  padding: 0 24rpx 24rpx; \r\n  display: flex; \r\n  gap: 16rpx; \r\n} \r\n.action-btn { \r\n  flex: 1; \r\n  color: #fff; \r\n  border-radius: 12rpx; \r\n  padding: 16rpx; \r\n  font-size: 28rpx; \r\n  text-align: center;\r\n} \r\n.refresh-btn { \r\n  background: #10b981; \r\n  box-shadow: 0 6rpx 16rpx rgba(16,185,129,0.18); \r\n}\r\n.adjust-btn { \r\n  background: #2176ff; \r\n  box-shadow: 0 6rpx 16rpx rgba(33,118,255,0.18); \r\n} \r\n\r\n/* 底部导航 */ \r\n.bottom-nav { \r\n  position: fixed; \r\n  left: 0; right: 0; bottom: 0; \r\n  background: #fff; \r\n  border-top: 1rpx solid #e2e8f0; \r\n  display: flex; \r\n  padding: 12rpx 24rpx; \r\n  gap: 12rpx; \r\n} \r\n.nav-item { \r\n  flex: 1; \r\n  background: linear-gradient(90deg, #479fff 0%, #2176ff 100%); \r\n  color: #fff; \r\n  border-radius: 12rpx; \r\n  padding: 16rpx 0; \r\n  text-align: center; \r\n  box-shadow: 0 6rpx 16rpx rgba(33,118,255,0.18); \r\n} \r\n.nav-icon { display: block; font-size: 28rpx; } \r\n.nav-text { display: block; font-size: 26rpx; font-weight: 600; margin-top: 6rpx; } \r\n</style>","import MiniProgramPage from 'D:/HuaweiMoveData/Users/zheng/Documents/GitHub/lh7772/校医院挂号系统/pages/doctor/schedule/main.vue'\nwx.createPage(MiniProgramPage)"],"names":["useUserStore","ref","computed","doctorApi","uniNavigateTo","uniShowToast","onMounted"],"mappings":";;;;;;;;AA6GA,UAAM,YAAYA,WAAAA,aAAc;AAChC,UAAM,aAAaC,cAAAA,IAAI;AAAA,MACrB,MAAM;AAAA,MACN,YAAY;AAAA,IACd,CAAC;AAED,UAAM,cAAcA,cAAG,IAAC,IAAI;AAC5B,UAAM,WAAWC,cAAAA,SAAS,MAAA;;AAAM,yBAAY,WAAS,eAAU,aAAV,mBAAoB,aAAY;AAAA,KAAC;AAGtF,UAAM,iBAAiB,YAAY;;AACjC,UAAI;AACF,kBAAU,gBAAiB;AAC3B,cAAM,UAAS,eAAU,aAAV,mBAAoB;AACnC,YAAI,CAAC;AAAQ;AACb,cAAM,UAAU,MAAMC,qBAAU,mBAAmB,MAAM;AACzD,mBAAW,QAAQ;AAAA,UACjB,OAAM,mCAAS,gBAAc,mCAAS,aAAY;AAAA,UAClD,aAAY,mCAAS,aAAY;AAAA,QAClC;AACD,oBAAY,SAAQ,mCAAS,aAAY;AAAA,MAC1C,SAAQ,GAAG;AAAA,MAEX;AAAA,IACH;AAGA,UAAM,YAAYF,cAAG,IAAC,EAAE;AAGxB,UAAM,WAAWA,cAAG,IAAC,EAAE;AACvB,UAAM,oBAAoBA,cAAG,IAAC,CAAC;AAG/B,UAAM,eAAeA,cAAG,IAAC,EAAE;AAE3B,UAAM,UAAU,CAAC,MAAM,GAAG,EAAE,YAAW,CAAE,IAAI,OAAO,EAAE,SAAQ,IAAG,CAAC,EAAE,SAAS,GAAE,GAAG,CAAC,IAAI,OAAO,EAAE,QAAS,CAAA,EAAE,SAAS,GAAE,GAAG,CAAC;AAE1H,UAAM,eAAe,MAAM;AACzB,YAAM,QAAQ,CAAE;AAChB,YAAM,WAAW,CAAC,MAAM,MAAM,MAAM,MAAM,MAAM,MAAM,IAAI;AAC1D,eAAS,IAAI,GAAG,IAAI,GAAG,KAAK;AAC1B,cAAM,OAAO,oBAAI,KAAM;AACvB,aAAK,QAAQ,KAAK,QAAO,IAAK,CAAC;AAC/B,cAAM,KAAK;AAAA,UACT,SAAS,SAAS,KAAK,QAAQ;AAAA,UAC/B,KAAK,KAAK,QAAS;AAAA,UACnB,OAAO,GAAG,KAAK,SAAQ,IAAK,CAAC;AAAA,UAC7B,UAAU;AAAA,QAChB,CAAK;AAAA,MACF;AACD,eAAS,QAAQ;AACjB,YAAM,QAAQ,oBAAI,KAAM;AACxB,gBAAU,QAAQ,GAAG,MAAM,YAAW,CAAE,IAAI,MAAM,SAAU,IAAG,CAAC,IAAI,MAAM,QAAO,CAAE;AAAA,IACrF;AAGA,UAAM,aAAa,CAAC,UAAU;AAC5B,wBAAkB,QAAQ;AAC1B,uBAAkB;AAAA,IACpB;AAGA,UAAM,iBAAiB,CAAC,UAAU;AAChC,UAAI,UAAU;AAAe,eAAO,MAAM,KAAK;AAC/C,UAAI,UAAU;AAAe,eAAO,MAAM,KAAK;AAC/C,UAAI,UAAU;AAAe,eAAO,MAAM,KAAK;AAC/C,aAAO;AAAA,IACT;AAEA,UAAM,mBAAmB,YAAY;AACnC,UAAI;AACF,cAAM,MAAM,SAAS,MAAM,kBAAkB,KAAK;AAClD,cAAM,YAAY,QAAQ,IAAI,QAAQ;AACtC,cAAM,OAAO,MAAME,qBAAU,aAAa,SAAS,OAAO,WAAW,CAAC;AACtE,qBAAa,SAAS,QAAQ,CAAA,GAAI,IAAI,QAAM;AAAA,UAC1C,YAAY,eAAe,EAAE,SAAS;AAAA,UACtC,YAAY,EAAE,UAAU;AAAA,UACxB,YAAY,EAAE,cAAc;AAAA,UAC5B,aAAa,EAAE,eAAe;AAAA,UAC9B,iBAAiB,EAAE,cAAc,MAAM,EAAE,eAAe;AAAA,QAC9D,EAAM;AAAA,MACH,SAAQ,GAAG;AAEV,cAAM,WAAW;AAAA,UACf,EAAE,YAAY,kBAAkB,YAAY,OAAO,YAAY,IAAI,aAAa,IAAI,gBAAgB,EAAG;AAAA,UACvG,EAAE,YAAY,kBAAkB,YAAY,OAAO,YAAY,IAAI,aAAa,IAAI,gBAAgB,EAAG;AAAA,UACvG,EAAE,YAAY,kBAAkB,YAAY,OAAO,YAAY,IAAI,aAAa,GAAG,gBAAgB,EAAG;AAAA,QACvG;AACD,qBAAa,QAAQ;AAAA,MACtB;AAAA,IACH;AAGA,UAAM,qBAAqB,MAAM;AAC/BC,oCAAc,EAAE,KAAK,gCAAgC;AAAA,IACvD;AAGA,UAAM,eAAe,MAAM;AACzBA,oCAAc,EAAE,KAAK,+BAA+B;AAAA,IACtD;AAGA,UAAM,cAAc,MAAM;AACxBA,oCAAc,EAAE,KAAK,+BAA+B;AAAA,IACtD;AAGA,UAAM,gBAAgB,YAAY;AAChCC,sBAAAA,aAAa,EAAE,OAAO,WAAW,MAAM,UAAS,CAAE;AAClD,UAAI;AACF,cAAM,iBAAkB;AACxBA,wBAAAA,aAAa,EAAE,OAAO,QAAQ,MAAM,UAAS,CAAE;AAAA,MAChD,SAAQ,OAAO;AACdA,wBAAAA,aAAa,EAAE,OAAO,QAAQ,MAAM,QAAO,CAAE;AAAA,MAC9C;AAAA,IACH;AAGA,UAAM,iBAAiB,CAAC,SAAS;AAC/B,YAAM,SAAQ,6BAAM,eAAc;AAClC,YAAM,UAAS,6BAAM,gBAAe;AACpC,YAAM,aAAY,6BAAM,mBAAmB,QAAQ;AACnD,UAAI,aAAa;AAAG,eAAO;AAC3B,YAAM,QAAQ,QAAQ,IAAI,SAAS,QAAQ;AAC3C,UAAI,YAAY,KAAK,SAAS;AAAK,eAAO;AAC1C,aAAO;AAAA,IACT;AAGA,UAAM,gBAAgB,CAAC,SAAS;AAC9B,YAAM,MAAM,eAAe,IAAI;AAC/B,UAAI,QAAQ;AAAe,eAAO;AAClC,UAAI,QAAQ;AAAe,eAAO;AAClC,aAAO;AAAA,IACT;AAEAC,kBAAAA,UAAU,MAAM;AACd,gBAAU,gBAAiB;AAC3B,mBAAc;AACd,qBAAgB,EAAC,QAAQ,gBAAgB;AAAA,IAC3C,CAAC;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;AC1PD,GAAG,WAAW,eAAe;"}
